    public function copyWithFixed(ThemeVersionAttributes $attributes, ?ThemeVersion $original = null): ThemeVersionAttributes
    {
        $this->logDebug("Copy with fixed for Theme version");
        $span = $this->startSpan("Copy with fixed for  Theme version");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new ThemeVersionPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

