    public function checkVisibility(Iterator|string|ThemeVersionRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Theme version");
        $span = $this->startSpan("Check visibility of an iterator for  Theme version");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new ThemeVersionRef($value));
            } elseif ($value instanceof ThemeVersionRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new ThemeVersionFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
